def pack_Excel_AddressableBlackListExcel(builder: flatbuffers.Builder, data: dict, encrypt=True) -> int:
    password = create_key("AddressableBlackList") if encrypt else None
    Id_val = convert_int(data.get('Id', 0), password)
    FolderPath_vec = 0
    if 'FolderPath' in data:
        FolderPath_items = data['FolderPath']
        FolderPath_offsets = [builder.CreateString(encrypt_string(item, password)) for item in FolderPath_items]
        Excel.AddressableBlackListExcel.StartFolderpathVector(builder, len(FolderPath_offsets))
        for offset in reversed(FolderPath_offsets):
            builder.PrependUOffsetTRelative(offset)
        FolderPath_vec = builder.EndVector()
    ResourcePath_vec = 0
    if 'ResourcePath' in data:
        ResourcePath_items = data['ResourcePath']
        ResourcePath_offsets = [builder.CreateString(encrypt_string(item, password)) for item in ResourcePath_items]
        Excel.AddressableBlackListExcel.StartResourcepathVector(builder, len(ResourcePath_offsets))
        for offset in reversed(ResourcePath_offsets):
            builder.PrependUOffsetTRelative(offset)
        ResourcePath_vec = builder.EndVector()
    Excel.AddressableBlackListExcel.Start(builder)
    Excel.AddressableBlackListExcel.AddId(builder, Id_val)
    Excel.AddressableBlackListExcel.AddFolderPath(builder, FolderPath_vec)
    Excel.AddressableBlackListExcel.AddResourcePath(builder, ResourcePath_vec)
    return Excel.AddressableBlackListExcel.End(builder)

